// model table bank.
// FUNCTION: FF7 0x004e1580
void __cdecl BattleFx_LimitLoadResTifa1(void)
{
    GfxModelTableBank *context;
    GfxResourceRequest requestBuffer;
    int kind;
    char pathBuffer[200];
    GfxResourceRequest *request;
    int defPtr;

    if (g_pBattle3dScene != 0 && g_BattleLimitTifaLoadedResTable == 0) {
        kind = 0x10;
        defPtr = (int)&g_BattleLimitTifaResourceDefs;
        context = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        request = &requestBuffer;
        Gfx_InitResourceRequest(request);
        request->groupTag = 0;
        // STRING: FF7 0x0083b388
        request->resourcePath = BattleFx_BuildResourcePath("limit2/tifa1", pathBuffer);
        Gfx_LoadModelTableIfAbsent(kind, defPtr, request, &g_BattleLimitTifaLoadedResTable, context);
    }
}

