    colorIncr = 0x100 / (g_BattleLimitTifaRibbonPointCount0 - g_BattleLimitTifaRibbonPointCount4);
    prim = (BattleGpuGradientQuad *)Gfx_GetPsxPacketScratchPtr();
    colorAccum = 0;
