            prim->tag = 0x8000000;
            prim->vertex0Red = colorAccum;
            prim->vertex2Red = 0;
            prim->vertex1Red = colorAccum + colorIncr;
            prim->vertex3Red = 0;
            prim->vertex0Green = colorAccum;
            prim->vertex2Green = 0;
            prim->vertex1Green = colorAccum + colorIncr;
            prim->vertex3Green = 0;
            prim->vertex0Blue = colorAccum;
            prim->vertex2Blue = colorAccum;
            prim->vertex1Blue = colorAccum + colorIncr;
            prim->vertex3Blue = colorAccum + colorIncr;
            colorAccum += colorIncr;
