        g_BattleLimitTifaRibbonInstances[g_BattleLimitTifaRibbonNextSlot].sampleSlot = 0;
        g_BattleLimitTifaRibbonInstances[g_BattleLimitTifaRibbonNextSlot].sampleCount = 5;
