/*
 * Scans the selected actor bone count and obtains each bone position, accumulating minimum and
 * maximum Y shorts and storing them through pMinY/pMaxY. With no iterations writes the initial
 * sentinel values 0x7FFF and -32768; no actor-index guard appears.
 */
// FUNCTION: FF7 0x004e8165
void __cdecl Battle_GetActorBoneYExtents(short actorIdx, short *pMinY, short *pMaxY)
{
    struct {
        int max;
        int i;
        int min;
        short pos[4];
    } local; /* Stack frame layout: see FRAME UNION in lib/codegen.h. */

    local.min = 0x7FFF;
    local.max = 0xFFFF8000;
    for (local.i = 0;
         local.i < g_BattleActorRecords[actorIdx].boneCount;
         local.i++) {
        Battle_GetBoneWorldPos(actorIdx, local.i, local.pos);
        if (local.pos[1] < local.min) {
            local.min = local.pos[1];
        }
        if (local.pos[1] > local.max) {
            local.max = local.pos[1];
        }
    }
    *pMinY = local.min;
    *pMaxY = local.max;
}

